// Rules audit 2026-11-18: events, profile/shared, clip readings and the incident status take only the shapes
// in shared/schemas (validators generated by tools/rules/gen_rules_validators.py), with sizes bounded.
import { doc, getDoc, setDoc, updateDoc, type Firestore } from "firebase/firestore";
import { afterAll, beforeEach, describe, it } from "vitest";
import { allFlags, clipReadingDoc, reportReading, routeRecord, validEvent } from "../fixtures";
import {
  admin, assertFails, assertSucceeds, clearFirestore, closeClients, commandClaims, dbAs, familyClaims, searcherClaims,
} from "../helpers";

const S = "searcher-uid", C = "command-uid", F = "family-uid";
const put = (db: Firestore, data: Record<string, unknown>) => setDoc(doc(db, `incidents/I1/events/${data.eventId as string}`), data);
const SHA = "a".repeat(64);
const camSighting = (over: Record<string, unknown> = {}) => ({
  personVisible: true, firstSeen: "00:02", lastSeen: "00:09", entryEdge: "away_from_camera", exitEdge: "toward_camera",
  topColor: "purple", bottomColor: "unknown", topType: "t".repeat(40), footwear: "f".repeat(40), headwear: "h".repeat(40),
  carriedItems: ["c".repeat(40), "d".repeat(40), "e".repeat(40)], keyFrame: { time: "00:05", box2d: [100, 200, 600, 400] },
  lighting: "low_light", legibility: "partial", evidence: "x".repeat(400), ...over,
});

beforeEach(async () => {
  await clearFirestore();
  await admin.db.doc("incidents/I1").set({ name: "Drill", mode: "drill", status: "open" });
});
afterAll(closeClients);

describe("event position, reading and route take only their schema shapes", () => {
  const db = () => dbAs(S, searcherClaims);
  it("schema-valid position, reading and route are accepted, at their largest too", async () => {
    await assertSucceeds(put(db(), validEvent(S, { position: { lat: 33.7, lon: -84.3, accuracyM: 5 }, reading: reportReading(), route: routeRecord() })));
    await assertSucceeds(put(db(), validEvent(S, { seq: 2, position: { lat: -90, lon: 180, accuracyM: null },
      reading: reportReading({ segmentIds: ["AA", "AB", "ABCDEFGHIJKLMNOP"], item: "i".repeat(40), footwear: "f".repeat(40),
                               carried: "c".repeat(40), evidenceQuote: "q".repeat(400), feature: "creek_or_drainage" }),
      route: routeRecord({ model: "m".repeat(80), blocked: "guardrail" }) })));
  });
  it("a route whose stage is picklist (a person picked the report from a list; no model ran) is accepted", async () => {
    await assertSucceeds(put(db(), validEvent(S, { route: routeRecord({ stage: "picklist", path: "rules", model: "", latencyMs: 0, sdkReported: false }) })));
  });
  it("a position with an extra key, a missing key, a wrong type, an out-of-range value or NaN is refused", async () => {
    for (const position of [{ lat: 1, lon: 2, accuracyM: 3, pad: "x" }, { lat: 1, lon: 2 }, { lat: 91, lon: 0, accuracyM: null },
                            { lat: 0, lon: 0, accuracyM: -1 }, { lat: "1", lon: 0, accuracyM: null }, { lat: NaN, lon: 0, accuracyM: null },
                            { lat: 0, lon: 0, accuracyM: "5" }]) {
      await assertFails(put(db(), validEvent(S, { position })));
    }
  });
  it("an oversized or unknown-keyed reading or route is refused (the log is append-only and every device syncs it)", async () => {
    for (const over of [{ reading: reportReading({ evidenceQuote: "q".repeat(401) }) }, { reading: reportReading({ pad: "x".repeat(10_000) }) },
                        { reading: reportReading({ segmentIds: ["AA", "AB", "AC", "AD"] }) }, { reading: reportReading({ kind: "x".repeat(50) }) },
                        { reading: reportReading({ segmentIds: ["ABCDEFGHIJKLMNOPQ"] }) }, { reading: reportReading({ segmentIds: [""] }) },
                        { reading: { pad: "x" } }, { route: routeRecord({ model: "m".repeat(81) }) }, { route: routeRecord({ extra: 1 }) },
                        { route: { pad: "x".repeat(10_000) } }]) {
      await assertFails(put(db(), validEvent(S, over)));
    }
  });
});

describe("the heaviest real events stay under the 1,000-expression rules limit", () => {
  const full = { position: { lat: 33.7, lon: -84.3, accuracyM: 4.5 }, route: routeRecord({ model: "m".repeat(80), blocked: "refusal" }),
    reading: reportReading({ segmentIds: ["AA", "AB", "ABCDEFGHIJKLMNOP"], item: "i".repeat(40), footwear: "f".repeat(40),
                             carried: "c".repeat(40), evidenceQuote: "q".repeat(400) }), rawText: "r".repeat(2000) };
  it("a cleared report with its effect inputs, a full reading, a route and a GPS position is accepted", async () => {
    await assertSucceeds(put(dbAs(S, searcherClaims), validEvent(S, { type: "cleared", ...full,
      effect: { kind: "cleared", segmentId: "AC", pod: 0.55, inputs: { coverage: 0.8, sweepWidthM: 16.4, trackLengthM: 950, areaM2: 15625, rdBasis: "hidden_target" } } })));
  });
  it("a clue with 64 influences, a full reading, a route and a GPS position is accepted", async () => {
    const influences = Object.fromEntries(Array.from({ length: 64 }, (_, i) => [`${String.fromCharCode(65 + Math.floor(i / 26))}${String.fromCharCode(65 + (i % 26))}`, "strong_for"]));
    await assertSucceeds(put(dbAs(C, commandClaims), validEvent(C, { role: "command", teamId: null, type: "clue", ...full,
      effect: { kind: "clue", influences, authenticity: "medium" } })));
  });
});

describe("size-pinned key sets: dropping any key for a stray one is refused", () => {
  it("each of the 25 event fields, swapped for a stray key, is refused", async () => {
    const base = validEvent(S, { reading: reportReading(), route: routeRecord(), position: { lat: 1, lon: 2, accuracyM: null } });
    for (const key of Object.keys(base)) {
      const { [key]: _drop, ...rest } = base;
      await assertFails(put(dbAs(S, searcherClaims), { ...rest, eventId: base.eventId, stray: null }));
    }
    await assertSucceeds(put(dbAs(S, searcherClaims), base));
  });
  it("each key of a cleared effect and its inputs, swapped for a stray key, is refused", async () => {
    const inputs = { coverage: 0.8, sweepWidthM: 16.4, trackLengthM: 950, areaM2: 15625, rdBasis: "hidden_target" };
    const effect = { kind: "cleared", segmentId: "AC", pod: 0.55, inputs };
    let seq = 1;
    for (const key of Object.keys(effect)) {
      const { [key]: _drop, ...rest } = effect;
      await assertFails(put(dbAs(S, searcherClaims), validEvent(S, { seq: seq++, type: "cleared", effect: { ...rest, stray: null } })));
    }
    for (const key of Object.keys(inputs)) {
      const { [key]: _drop, ...rest } = inputs;
      await assertFails(put(dbAs(S, searcherClaims), validEvent(S, { seq: seq++, type: "cleared", effect: { ...effect, inputs: { ...rest, stray: null } } })));
    }
    await assertSucceeds(put(dbAs(S, searcherClaims), validEvent(S, { seq: seq++, type: "cleared", effect })));
  });
});

describe("the largest camera sighting stays under the 1,000-expression rules limit", () => {
  it("a family camera sighting with every field at its maximum is accepted", async () => {
    await admin.db.doc(`incidents/I1/clipReadings/${SHA}`).set({ sha256: SHA, createdByUid: F, reading: null });
    await assertSucceeds(put(dbAs(F, familyClaims), validEvent(F, {
      role: "family", teamId: null, reporter: "camera", inputMethod: "clip", positionSource: "camera_pin", type: "camera_sighting",
      effect: { kind: "none", why: "incorporated_in_prior" }, position: { lat: 33.7, lon: -84.3, accuracyM: 12 }, route: routeRecord({ model: "m".repeat(80) }),
      reading: { sighting: camSighting(), clipSha256: SHA, clipStartMs: 1795860000000, clockConfirmed: true, cameraFacingDeg: 315 },
    })));
  });
  it("a camera sighting with a fourth carried item or an oversized field is refused", async () => {
    await admin.db.doc(`incidents/I1/clipReadings/${SHA}`).set({ sha256: SHA, createdByUid: F, reading: null });
    for (const sighting of [camSighting({ carriedItems: ["a", "b", "c", "d"] }), camSighting({ evidence: "x".repeat(401) }),
                            camSighting({ keyFrame: { time: "00:05", box2d: [1, 2, 3] } }), camSighting({ pad: 1 })]) {
      await assertFails(put(dbAs(F, familyClaims), validEvent(F, {
        role: "family", teamId: null, reporter: "camera", inputMethod: "clip", positionSource: "camera_pin", type: "camera_sighting",
        effect: { kind: "none", why: "incorporated_in_prior" },
        reading: { sighting, clipSha256: SHA, clipStartMs: 1795860000000, clockConfirmed: true, cameraFacingDeg: 90 },
      })));
    }
  });
});

describe("profile/shared types every key it allows", () => {
  const full = { answersTo: "Mom", nickname: "", ageYears: 81, gender: "woman", appearance: "short", heightFt: 5, heightIn: 2,
    weightLb: 120, hair: "white", eyeColor: "brown", primaryLanguage: "", clothingLastWorn: "red coat", mobilityAids: ["cane"],
    dementiaType: "alzheimers", flags: allFlags(["mayNotRespond"]), triggersToAvoid: "", bestApproach: "", uniqueDescription: "",
    photoTakenOn: "2026-11-10", approachNoteIds: ["may_not_respond", "approach_calm"] };
  it("the full shared profile the apps write is accepted", async () => {
    await assertSucceeds(setDoc(doc(dbAs(F, familyClaims), "incidents/I1/profile/shared"), full));
  });
  it("a partial profile is refused: readers can rely on all 20 keys (review M4)", async () => {
    const db = dbAs(F, familyClaims);
    await assertFails(setDoc(doc(db, "incidents/I1/profile/shared"), { nickname: "Nana" }));
    const { approachNoteIds: _a, ...noNotes } = full;
    await assertFails(setDoc(doc(db, "incidents/I1/profile/shared"), noNotes));
  });
  it("free text or a wrong type in any typed key is refused", async () => {
    const db = dbAs(F, familyClaims);
    for (const over of [{ dementiaType: "lived at 12 Elm St until 2019" }, { mobilityAids: [{ label: "Old home", address: "12 Elm St" }] },
                        { mobilityAids: ["cane", "jetpack"] }, { photoTakenOn: "last week" }, { ageYears: "eighty" }, { ageYears: 200 },
                        { heightIn: 12 }, { answersTo: "a".repeat(61) }, { gender: "g".repeat(41) }, { flags: { likelyToHide: true } },
                        { approachNoteIds: ["see the old house on Elm"] }, { approachNoteIds: Array(22).fill("approach_calm") }]) {
      await assertFails(setDoc(doc(db, "incidents/I1/profile/shared"), { ...full, ...over }));
    }
  });
});

describe("clip readings expire within 31 days; the incident status stays in its enum", () => {
  it("a clip reading's expiresAt must be 31 to 33 days after the server's time; clients write 32 (review round 2)", async () => {
    const db = dbAs(F, familyClaims);
    const DAY = 86_400_000, MIN = 60_000;
    await assertSucceeds(setDoc(doc(db, `incidents/I1/clipReadings/${SHA}`), clipReadingDoc("I1", SHA, F)));
    const cases: [number, boolean][] = [[31 * DAY - MIN, false], [31 * DAY + MIN, true], [33 * DAY - MIN, true], [33 * DAY + MIN, false],
                                         [30 * DAY, false], [-MIN, false]];
    for (const [i, [offset, ok]] of cases.entries()) {
      const sha = String(i + 1).repeat(64);
      const write = setDoc(doc(db, `incidents/I1/clipReadings/${sha}`), clipReadingDoc("I1", sha, F, { expiresAt: new Date(Date.now() + offset) }));
      await (ok ? assertSucceeds(write) : assertFails(write));
    }
  });
  it("command cannot set the status outside open, found and closed, or remove it", async () => {
    const db = dbAs(C, commandClaims);
    await assertSucceeds(setDoc(doc(db, "incidents/I1"), { status: "found" }, { merge: true }));
    await assertFails(setDoc(doc(db, "incidents/I1"), { status: "Closed" }, { merge: true }));
    await assertFails(setDoc(doc(db, "incidents/I1"), { name: "Drill", mode: "drill" }));
  });
  it("command sets the urgency conditions only in their schema shape", async () => {
    const db = dbAs(C, commandClaims);
    await assertSucceeds(setDoc(doc(db, "incidents/I1"), { conditions: { tempF: 41, wet: true, setAtMs: 1795860000000 } }, { merge: true }));
    await assertSucceeds(setDoc(doc(db, "incidents/I1"), { conditions: { tempF: null, wet: null, setAtMs: 1795860000000 } }, { merge: true }));
    for (const conditions of [{ tempF: "41", wet: true, setAtMs: 1 }, { tempF: 41, wet: "yes", setAtMs: 1 }, { tempF: 41, wet: true },
                              { tempF: 41, wet: true, setAtMs: 1, note: "x" }, { tempF: 400, wet: false, setAtMs: 1 }]) {
      // updateDoc replaces the whole field; a merging setDoc would deep-merge it with the earlier valid map.
      await assertFails(updateDoc(doc(db, "incidents/I1"), { conditions }));
    }
  });
  it("command cannot write mediaDeletedAt, which only the media sweep sets (review, low)", async () => {
    await assertFails(setDoc(doc(dbAs(C, commandClaims), "incidents/I1"), { mediaDeletedAt: new Date() }, { merge: true }));
    // Nor mediaSweepEmpty, which would hide a sandbox from the sweep.
    await assertFails(setDoc(doc(dbAs(C, commandClaims), "incidents/I1"), { mediaSweepEmpty: true }, { merge: true }));
  });
});

describe("ops/storage is the one public doc: readable without sign-in, writable by nobody", () => {
  it("anyone reads ops/storage; no one writes it; other ops docs stay closed", async () => {
    await admin.db.doc("ops/storage").set({ lifecycleOk: true });
    await admin.db.doc("ops/other").set({ x: 1 });
    await assertSucceeds(getDoc(doc(dbAs(null), "ops/storage")));
    await assertFails(getDoc(doc(dbAs(null), "ops/other")));
    await assertFails(setDoc(doc(dbAs(C, commandClaims), "ops/storage"), { lifecycleOk: true }));
    await assertFails(setDoc(doc(dbAs(null), "ops/storage"), { lifecycleOk: true }));
  });
});
